action.code:
lfs_off_t size = *off;
uint32_t index = 0;

if (size == 0) {
    *off = 0;
    return 0;
}

// Count trailing zeros to determine the skip index
index = lfs_ctz(size);

// Calculate the skip distance (2^index)
*off = (lfs_off_t)(1 << index);

return index;

